-- Disposable users and editions only. Execute with the other acceptance suites inside BEGIN / ROLLBACK.
create temporary table workspace_people_test_result(checks integer,credentials_preserved boolean,keynotes_preserved boolean);
do $$
declare ids uuid[]:=array[gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid()];
 sessions uuid[]:=array[gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid()];
 u uuid;p jsonb;second jsonb;g jsonb;d jsonb;snap jsonb;found jsonb;task jsonb;a uuid;n integer;checks integer:=0;denied boolean;operation text;cap timestamptz:=now()+interval '10 days';shorter timestamptz:=now()+interval '5 days';before_notices integer;passwords text;keynotes text;
begin
 select md5(coalesce(string_agg(id::text||coalesce(encrypted_password,''),'' order by id),'')) into passwords from auth.users;
 select md5(coalesce(string_agg(to_jsonb(k)::text,'' order by id),'')) into keynotes from public.gba_keynotes k;
 for n in 1..6 loop
  insert into auth.users(id,email,aud,role,raw_user_meta_data,is_sso_user,is_anonymous,created_at,updated_at) values(ids[n],'workspace-people-test-'||ids[n]||'@example.invalid','authenticated','authenticated',jsonb_build_object('nombre','people-test-'||ids[n]),false,false,now(),now());
  insert into auth.sessions(id,user_id,created_at,updated_at) values(sessions[n],ids[n],now(),now());
 end loop;
 select id into u from public.workspace_units where slug='gimg';
 insert into public.workspace_unit_memberships(unit_id,user_id,membership_status) values(u,ids[1],'active');
 insert into public.workspace_access_grants(user_id,unit_id,access_role,scope_type,scope_id,reason) values(ids[1],u,'gimg_direction','unit',u,'Rollback-only people acceptance');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',ids[1],'session_id',sessions[1],'role','authenticated')::text,true);perform set_config('role','authenticated',true);
 p:=public.workspace_command('project.create',jsonb_build_object('unit_id',u,'title','Rollback-only people edition','ends_at',now()+interval '30 days'));
 second:=public.workspace_command('project.create',jsonb_build_object('unit_id',u,'title','Not shared with consultation'));
 select id into a from public.workspace_areas where project_id=(p->>'id')::uuid and specialty='research';
 found:=public.workspace_find_profile(u,' @PEOPLE-TEST-'||ids[2]);
 if found->'profile'->>'id' is distinct from ids[2]::text or found->'profile'?'email' or (found->>'alreadyMember')::boolean then raise exception 'Exact private lookup failed';end if;checks:=checks+1;
 perform public.workspace_people_action(u,'invite',jsonb_build_object('userId',ids[2],'mode','team','expiresAt',cap));
 denied:=false;begin perform public.workspace_people_action(u,'invite',jsonb_build_object('userId',ids[2],'mode','team'));exception when others then denied:=true;end;if not denied then raise exception 'Duplicate invitation accepted';end if;checks:=checks+1;
 perform set_config('role','postgres',true);select count(*) into before_notices from workspace_private.notifications where recipient_id=ids[2] and event_type='access.updated';perform set_config('role','authenticated',true);
 g:=public.workspace_people_action(u,'assign',jsonb_build_object('userId',ids[2],'cargoKey','contributor','projectId',p->>'id','functionKey','research','expiresAt',now()+interval '30 days'));
 if not (g->>'clamped')::boolean or (g->>'expiresAt')::timestamptz<>cap then raise exception 'Membership cap was not applied';end if;checks:=checks+1;
 perform set_config('role','postgres',true);
 if not exists(select 1 from public.workspace_assignments where grant_id=(g->>'id')::uuid and function_key='research' and area_id=a and expires_at=cap) then raise exception 'Atomic cargo pairing missing';end if;checks:=checks+1;
 if (select count(*) from workspace_private.notifications where recipient_id=ids[2] and event_type='access.updated')<>before_notices+1 then raise exception 'Cargo notifications duplicated';end if;checks:=checks+1;
 perform set_config('role','authenticated',true);
 snap:=public.workspace_members_snapshot(u,(p->>'id')::uuid);
 if snap->'matrix'->'gimg_direction'->>'publication.approve_final'<>'U' or snap->'delegableKeys'?'publication.approve_final' or snap->'delegableKeys'?'unit.roles.grant' or snap->'delegableKeys'?'asset.delete_physical' then raise exception 'Canonical matrix or locked keys failed';end if;checks:=checks+1;
 perform public.workspace_people_action(u,'expiry',jsonb_build_object('grantId',g->>'id','expiresAt',shorter,'reason','Shorter cycle acceptance'));
 perform set_config('role','postgres',true);if not exists(select 1 from public.workspace_assignments where grant_id=(g->>'id')::uuid and expires_at=shorter) then raise exception 'Assignment expiry did not follow grant';end if;checks:=checks+1;perform set_config('role','authenticated',true);
 denied:=false;begin perform public.workspace_people_action(u,'assign',jsonb_build_object('userId',ids[2],'cargoKey','contributor','projectId',p->>'id','functionKey','research'));exception when others then denied:=true;end;if not denied then raise exception 'Duplicate live scope accepted';end if;checks:=checks+1;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',ids[2],'session_id',sessions[2],'role','authenticated')::text,true);
 foreach operation in array array['invite','assign','expiry','remove','membership','delegate','revoke'] loop
  denied:=false;begin perform public.workspace_people_action(u,operation,jsonb_build_object('userId',ids[2],'grantId',g->>'id','status','active'));exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Contributor called %',operation;end if;checks:=checks+1;
 end loop;
 denied:=false;begin perform public.workspace_find_profile(u,'people-test-'||ids[3]);exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Contributor searched private account directory';end if;checks:=checks+1;
 denied:=false;begin perform 1 from workspace_private.written_briefs;exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Direct mandate table exposed';end if;checks:=checks+1;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',ids[1],'session_id',sessions[1],'role','authenticated')::text,true);
 denied:=false;begin perform public.workspace_people_action(u,'delegate',jsonb_build_object('delegateId',ids[2],'projectId',p->>'id','permissionKeys',jsonb_build_array('publication.approve_final'),'expiresAt',shorter,'brief','Forbidden final publication delegation'));exception when others then denied:=true;end;if not denied then raise exception 'Final authority delegated';end if;checks:=checks+1;
 denied:=false;begin perform public.workspace_people_action(u,'delegate',jsonb_build_object('delegateId',ids[2],'projectId',p->>'id','permissionKeys',jsonb_build_array('content.comment'),'expiresAt',shorter,'brief','[escribe el motivo] unfinished mandate'));exception when others then denied:=true;end;if not denied then raise exception 'Placeholder mandate accepted';end if;checks:=checks+1;
 d:=public.workspace_people_action(u,'delegate',jsonb_build_object('delegateId',ids[2],'projectId',p->>'id','permissionKeys',jsonb_build_array('content.comment'),'expiresAt',shorter,'brief','May comment on this disposable edition to support research review, without approving publication.'));
 perform set_config('request.jwt.claims',jsonb_build_object('sub',ids[2],'session_id',sessions[2],'role','authenticated')::text,true);
 if not workspace_private.allowed('content.comment',u,(p->>'id')::uuid,a) or workspace_private.allowed('content.comment',u,(second->>'id')::uuid) then raise exception 'Scoped mandate failed';end if;checks:=checks+1;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',ids[1],'session_id',sessions[1],'role','authenticated')::text,true);
 perform public.workspace_people_action(u,'revoke',jsonb_build_object('delegationId',d->>'id','reason','End of disposable mandate'));
 task:=public.workspace_command('task.create',jsonb_build_object('project_id',p->>'id','area_id',a,'title','Assigned cargo test','responsible_id',ids[2]));
 perform set_config('request.jwt.claims',jsonb_build_object('sub',ids[2],'session_id',sessions[2],'role','authenticated')::text,true);
 if not exists(select 1 from public.workspace_projects where id=(p->>'id')::uuid) then raise exception 'Assigned contributor cannot read edition';end if;checks:=checks+1;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',ids[1],'session_id',sessions[1],'role','authenticated')::text,true);
 perform public.workspace_people_action(u,'remove',jsonb_build_object('grantId',g->>'id','reason','End of disposable cargo'));
 perform set_config('request.jwt.claims',jsonb_build_object('sub',ids[2],'session_id',sessions[2],'role','authenticated')::text,true);
 if exists(select 1 from public.workspace_projects where id=(p->>'id')::uuid) then raise exception 'Revoked cargo retained edition access';end if;checks:=checks+1;
 perform set_config('role','postgres',true);if not exists(select 1 from public.workspace_access_grants where id=(g->>'id')::uuid and revoked_at is not null) or not exists(select 1 from workspace_private.written_briefs b join public.workspace_delegations dl on dl.written_brief_id=b.id where dl.id=(d->>'id')::uuid and revoked_at is not null) then raise exception 'Revocation removed history';end if;checks:=checks+1;perform set_config('role','authenticated',true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',ids[1],'session_id',sessions[1],'role','authenticated')::text,true);
 perform public.workspace_people_action(u,'membership',jsonb_build_object('userId',ids[2],'status','suspended','reason','Disposable suspended state'));
 denied:=false;begin perform public.workspace_people_action(u,'assign',jsonb_build_object('userId',ids[2],'cargoKey','quality','projectId',p->>'id'));exception when others then denied:=true;end;if not denied then raise exception 'Suspended person received cargo';end if;checks:=checks+1;
 perform public.workspace_people_action(u,'membership',jsonb_build_object('userId',ids[2],'status','active','expiresAt',cap));
 g:=public.workspace_people_action(u,'assign',jsonb_build_object('userId',ids[2],'cargoKey','contributor','projectId',p->>'id','functionKey','photography','expiresAt',cap));
 perform public.workspace_command('member.save',jsonb_build_object('unit_id',u,'user_id',ids[2],'membership_status','active','expires_at',shorter,'reason','Legacy membership cap'));
 perform set_config('role','postgres',true);if exists(select 1 from public.workspace_access_grants where user_id=ids[2] and revoked_at is null and (expires_at is null or expires_at>shorter)) or exists(select 1 from public.workspace_assignments where user_id=ids[2] and (expires_at is null or expires_at>shorter)) then raise exception 'Legacy member mutation bypassed cap';end if;checks:=checks+1;
 if not exists(select 1 from public.workspace_assignments aa join public.workspace_areas ar on ar.id=aa.area_id where aa.grant_id=(g->>'id')::uuid and aa.function_key='photography' and ar.name='Fotografía') then raise exception 'Photography used synthetic or illustration scope';end if;checks:=checks+1;
 update public.workspace_unit_memberships set expires_at=now()-interval '1 second' where unit_id=u and user_id=ids[2];perform set_config('role','authenticated',true);
 denied:=false;begin perform public.workspace_people_action(u,'assign',jsonb_build_object('userId',ids[2],'cargoKey','quality','projectId',p->>'id'));exception when others then denied:=true;end;if not denied then raise exception 'Expired membership received cargo';end if;checks:=checks+1;
 perform public.workspace_people_action(u,'invite',jsonb_build_object('userId',ids[3],'mode','team'));
 perform public.workspace_people_action(u,'assign',jsonb_build_object('userId',ids[3],'cargoKey','coordination','projectId',p->>'id','expiresAt',cap));
 perform set_config('request.jwt.claims',jsonb_build_object('sub',ids[3],'session_id',sessions[3],'role','authenticated')::text,true);
 denied:=false;begin perform public.workspace_people_action(u,'invite',jsonb_build_object('userId',ids[4],'mode','team'));exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Coordinator invited without mandate';end if;checks:=checks+1;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',ids[1],'session_id',sessions[1],'role','authenticated')::text,true);
 perform public.workspace_people_action(u,'delegate',jsonb_build_object('delegateId',ids[3],'scopeType','unit','permissionKeys',jsonb_build_array('unit.members.invite'),'expiresAt',shorter,'brief','May incorporate the disposable test team during this cycle; no role-grant authority.'));
 perform set_config('request.jwt.claims',jsonb_build_object('sub',ids[3],'session_id',sessions[3],'role','authenticated')::text,true);
 perform public.workspace_people_action(u,'invite',jsonb_build_object('userId',ids[4],'mode','team'));checks:=checks+1;
 denied:=false;begin perform public.workspace_people_action(u,'assign',jsonb_build_object('userId',ids[4],'cargoKey','quality','projectId',p->>'id'));exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Invitation mandate granted roles';end if;checks:=checks+1;
 denied:=false;begin perform public.workspace_people_action(u,'invite',jsonb_build_object('userId',ids[5],'mode','viewer','projectId',p->>'id'));exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Invitation mandate shared a project';end if;
 perform set_config('role','postgres',true);if exists(select 1 from public.workspace_unit_memberships where user_id=ids[5]) then raise exception 'Failed compound invite left membership';end if;checks:=checks+1;perform set_config('role','authenticated',true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',ids[1],'session_id',sessions[1],'role','authenticated')::text,true);
 perform public.workspace_people_action(u,'invite',jsonb_build_object('userId',ids[5],'mode','viewer','projectId',p->>'id'));
 perform public.workspace_people_action(u,'invite',jsonb_build_object('userId',ids[6],'mode','reserve'));
 perform set_config('request.jwt.claims',jsonb_build_object('sub',ids[5],'session_id',sessions[5],'role','authenticated')::text,true);
 if not exists(select 1 from public.workspace_projects where id=(p->>'id')::uuid) or exists(select 1 from public.workspace_projects where id=(second->>'id')::uuid) or workspace_private.allowed('content.edit_any_scoped',u,(p->>'id')::uuid) or workspace_private.allowed('asset.download_source',u,(p->>'id')::uuid) then raise exception 'Consultation not explicitly read-only';end if;checks:=checks+1;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',ids[1],'session_id',sessions[1],'role','authenticated')::text,true);
 select jsonb_build_object('id',id) into g from public.workspace_access_grants where user_id=ids[5] and access_role='gimg_viewer' and revoked_at is null;
 perform public.workspace_people_action(u,'expiry',jsonb_build_object('grantId',g->>'id','expiresAt',shorter,'reason','Shorten explicitly shared consultation'));
 perform set_config('role','postgres',true);if not exists(select 1 from public.workspace_delegations where grant_id=(g->>'id')::uuid and expires_at=shorter) then raise exception 'Viewer sharing expiry not coupled';end if;checks:=checks+1;perform set_config('role','authenticated',true);
 perform public.workspace_people_action(u,'remove',jsonb_build_object('grantId',g->>'id','reason','End of explicitly shared consultation'));
 perform set_config('request.jwt.claims',jsonb_build_object('sub',ids[5],'session_id',sessions[5],'role','authenticated')::text,true);
 if exists(select 1 from public.workspace_projects where id=(p->>'id')::uuid) then raise exception 'Viewer retained sharing after cargo revoke';end if;checks:=checks+1;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',ids[6],'session_id',sessions[6],'role','authenticated')::text,true);
 if jsonb_array_length(public.workspace_context()->'units')<>0 then raise exception 'Reserve received operational access';end if;checks:=checks+1;
 perform set_config('role','postgres',true);
 if not exists(select 1 from public.workspace_audit where action='people.cargo_assigned' and context->>'resolved_user_id'=ids[2]::text and actor_id=ids[1]) then raise exception 'Compound operation not audited';end if;checks:=checks+1;
 insert into workspace_people_test_result values(checks,passwords=(select md5(coalesce(string_agg(id::text||coalesce(encrypted_password,''),'' order by id),'')) from auth.users where id<>all(ids)),keynotes=(select md5(coalesce(string_agg(to_jsonb(k)::text,'' order by id),'')) from public.gba_keynotes k));
 perform set_config('request.jwt.claims','{}',true);
end;$$;
